/**
 * Legal Knowledge Base Seed Data
 *
 * ~280 glossary terms, ~55 statutes, ~20 precedents
 * Matching schema columns in schema-postgres.ts:
 *   legal_glossary: term, definition, category, jurisdiction, related_terms (jsonb), sources (jsonb)
 *   statutes: title, content, jurisdiction, section, category, source_url, effective_date
 *   legal_precedents: title, summary, citation, court, decision_date
 */

// ─── GLOSSARY ────────────────────────────────────────────────────────

export interface GlossaryEntry {
	term: string;
	definition: string;
	category: string;
	jurisdiction: string;
	relatedTerms: string[];
	sources: string[];
}

export const glossaryTerms: GlossaryEntry[] = [
	// ── Criminal ──
	{ term: 'Mens Rea', definition: 'The mental element of a crime; the guilty mind or criminal intent required to establish criminal liability. Different levels include purposely, knowingly, recklessly, and negligently.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['intent', 'actus reus', 'culpability', 'scienter'], sources: ["Black's Law Dictionary", 'Model Penal Code §2.02'] },
	{ term: 'Actus Reus', definition: 'The physical act or unlawful omission that constitutes the objective element of a crime, as distinguished from the mental state (mens rea) of the accused.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['mens rea', 'voluntary act', 'omission'], sources: ["Black's Law Dictionary"] },
	{ term: 'Felony', definition: 'A serious criminal offense typically punishable by imprisonment for more than one year or by death. Distinguished from misdemeanors by the severity of the punishment.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['misdemeanor', 'infraction', 'wobbler', 'sentencing'], sources: ["Black's Law Dictionary", '18 USC §3559'] },
	{ term: 'Misdemeanor', definition: 'A criminal offense less serious than a felony, typically punishable by fine, penalty, forfeiture, or confinement in a local facility for less than one year.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['felony', 'infraction', 'petty offense'], sources: ["Black's Law Dictionary"] },
	{ term: 'Arraignment', definition: 'A court proceeding in which a criminal defendant is formally advised of the charges and asked to enter a plea of guilty, not guilty, or no contest.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['plea', 'indictment', 'information', 'initial appearance'], sources: ["Black's Law Dictionary", 'Fed. R. Crim. P. 10'] },
	{ term: 'Bail', definition: 'Security (usually a sum of money) exchanged for the release of an arrested person as a guarantee of that person\'s appearance at trial. Can be denied for flight risk or danger to community.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['bond', 'pretrial release', 'surety', 'recognizance'], sources: ["Black's Law Dictionary", '8th Amendment'] },
	{ term: 'Plea Bargain', definition: 'A negotiated agreement between the prosecution and the defense whereby the defendant pleads guilty to a lesser offense or to one of multiple charges in exchange for concessions by the prosecutor.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['plea agreement', 'guilty plea', 'charge bargaining', 'sentence bargaining'], sources: ["Black's Law Dictionary", 'Fed. R. Crim. P. 11'] },
	{ term: 'Indictment', definition: 'A formal written accusation of a crime issued by a grand jury after examining evidence presented by a prosecutor. Required for federal felony prosecutions under the Fifth Amendment.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['grand jury', 'information', 'presentment', 'true bill'], sources: ["Black's Law Dictionary", 'U.S. Const. Amend. V'] },
	{ term: 'Grand Jury', definition: 'A body of citizens (typically 16-23 members) convened to evaluate whether there is probable cause to charge someone with a crime. Operates in secret and issues indictments.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['indictment', 'true bill', 'no bill', 'subpoena'], sources: ["Black's Law Dictionary", 'Fed. R. Crim. P. 6'] },
	{ term: 'Probation', definition: 'A sentencing alternative to incarceration allowing the convicted person to remain in the community under supervision and subject to conditions imposed by the court.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['parole', 'supervised release', 'conditions', 'revocation'], sources: ["Black's Law Dictionary", '18 USC §3561'] },
	{ term: 'Parole', definition: 'The conditional release of a prisoner before the completion of their sentence, subject to supervision and specific conditions. Violation can result in return to incarceration.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['probation', 'supervised release', 'good time', 'revocation'], sources: ["Black's Law Dictionary"] },
	{ term: 'Accomplice', definition: 'A person who knowingly, voluntarily, and intentionally assists another person in committing a crime. An accomplice is equally liable for the criminal act.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['accessory', 'aiding and abetting', 'conspiracy', 'principal'], sources: ["Black's Law Dictionary", '18 USC §2'] },
	{ term: 'Manslaughter', definition: 'The unlawful killing of a human being without malice aforethought. Voluntary manslaughter involves intentional killing in the heat of passion; involuntary involves unintentional killing through criminal negligence.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['murder', 'homicide', 'heat of passion', 'negligent homicide'], sources: ["Black's Law Dictionary", 'CA Penal Code §192'] },
	{ term: 'Arson', definition: 'The willful and malicious burning or charring of property. Classified by degree depending on whether the structure was inhabited, whether persons were injured, and whether insurance fraud was intended.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['fire', 'insurance fraud', 'malicious mischief'], sources: ["Black's Law Dictionary", 'CA Penal Code §451'] },
	{ term: 'Recidivism', definition: 'The tendency of a convicted criminal to reoffend. Recidivism rates are used in sentencing, parole decisions, and criminal justice policy evaluation.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['repeat offender', 'three strikes', 'habitual offender', 'rehabilitation'], sources: ["Black's Law Dictionary", 'Bureau of Justice Statistics'] },
	{ term: 'Human Trafficking', definition: 'The recruitment, harboring, transportation, or obtaining of a person through force, fraud, or coercion for the purpose of exploitation, including forced labor, sexual servitude, or involuntary servitude.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['forced labor', 'sexual exploitation', 'smuggling', 'Trafficking Victims Protection Act'], sources: ['18 USC §1589-1592', 'CA Penal Code §236.1'] },

	// ── Constitutional ──
	{ term: 'Habeas Corpus', definition: 'A writ requiring a person under arrest to be brought before a judge or court, especially to determine whether the detention is lawful. Protects against unlawful and indefinite imprisonment.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['writ', 'detention', 'due process', 'unlawful imprisonment'], sources: ['U.S. Const. Art. I, §9', '28 USC §2241', "Black's Law Dictionary"] },
	{ term: 'Due Process', definition: 'The constitutional guarantee that all legal proceedings will be fair and that a person will be given notice and an opportunity to be heard before the government acts to take away life, liberty, or property.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['procedural due process', 'substantive due process', 'equal protection', 'fundamental rights'], sources: ['U.S. Const. Amend. V', 'U.S. Const. Amend. XIV'] },
	{ term: 'Double Jeopardy', definition: 'The constitutional protection against being prosecuted twice for the same offense after acquittal or conviction. The Fifth Amendment prohibits the government from re-trying a defendant for the same crime.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['acquittal', 'Fifth Amendment', 'collateral estoppel', 'lesser included offense'], sources: ['U.S. Const. Amend. V', "Black's Law Dictionary"] },
	{ term: 'Miranda Rights', definition: 'The constitutional rights that law enforcement must inform a suspect of before custodial interrogation: the right to remain silent, that statements may be used against them, the right to an attorney, and the right to a court-appointed attorney if indigent.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Fifth Amendment', 'custodial interrogation', 'right to counsel', 'self-incrimination'], sources: ['Miranda v. Arizona, 384 U.S. 436 (1966)'] },
	{ term: 'Probable Cause', definition: 'A reasonable ground for belief in certain alleged facts that would warrant a person of reasonable caution to believe that a crime has been or is being committed, or that evidence of a crime exists at a particular location.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['reasonable suspicion', 'search warrant', 'arrest', 'Fourth Amendment'], sources: ['U.S. Const. Amend. IV', "Black's Law Dictionary"] },
	{ term: 'Search and Seizure', definition: 'The Fourth Amendment protection against unreasonable government intrusion into a person\'s body, home, property, or electronic communications. Requires a warrant based on probable cause, with exceptions.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Fourth Amendment', 'warrant', 'probable cause', 'exclusionary rule', 'plain view'], sources: ['U.S. Const. Amend. IV', 'Mapp v. Ohio, 367 U.S. 643 (1961)'] },
	{ term: 'Equal Protection', definition: 'The Fourteenth Amendment guarantee that no state shall deny to any person within its jurisdiction the equal protection of the laws. Requires that similarly situated persons be treated alike.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Fourteenth Amendment', 'strict scrutiny', 'rational basis', 'intermediate scrutiny', 'discrimination'], sources: ['U.S. Const. Amend. XIV, §1'] },
	{ term: 'Cruel and Unusual Punishment', definition: 'The Eighth Amendment prohibition against punishments that are barbaric, disproportionate to the crime, or that violate evolving standards of decency. Applied to conditions of confinement and sentencing.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Eighth Amendment', 'death penalty', 'proportionality', 'conditions of confinement'], sources: ['U.S. Const. Amend. VIII'] },

	// ── Evidence ──
	{ term: 'Hearsay', definition: 'An out-of-court statement offered in evidence to prove the truth of the matter asserted. Generally inadmissible unless it falls within a recognized exception such as excited utterance, dying declaration, or business records.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['hearsay exception', 'confrontation clause', 'business records', 'excited utterance'], sources: ['Fed. R. Evid. 801-807', 'CA Evid. Code §1200'] },
	{ term: 'Burden of Proof', definition: 'The obligation to prove assertions of fact in a legal proceeding. In criminal cases, the prosecution bears the burden of proving guilt beyond a reasonable doubt. In civil cases, the standard is typically preponderance of the evidence.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['beyond reasonable doubt', 'preponderance', 'clear and convincing', 'presumption of innocence'], sources: ["Black's Law Dictionary", 'In re Winship, 397 U.S. 358 (1970)'] },
	{ term: 'Chain of Custody', definition: 'The chronological documentation showing the seizure, custody, control, transfer, analysis, and disposition of physical or electronic evidence. Required to ensure evidence integrity and admissibility.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['evidence integrity', 'authentication', 'forensics', 'tamper-proof'], sources: ["Black's Law Dictionary", 'Fed. R. Evid. 901'] },
	{ term: 'Expert Witness', definition: 'A person qualified by knowledge, skill, experience, training, or education to provide testimony in the form of an opinion on matters beyond the understanding of ordinary people.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['Daubert standard', 'Frye test', 'opinion testimony', 'qualification'], sources: ['Fed. R. Evid. 702', 'Daubert v. Merrell Dow, 509 U.S. 579 (1993)'] },
	{ term: 'Circumstantial Evidence', definition: 'Evidence that requires an inference to connect it to a conclusion of fact. Unlike direct evidence, it does not directly prove a fact but allows a reasonable inference to be drawn.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['direct evidence', 'inference', 'presumption', 'weight of evidence'], sources: ["Black's Law Dictionary"] },
	{ term: 'Admissibility', definition: 'The quality of evidence that makes it proper to be received by a court for consideration. Evidence must be relevant, material, competent, and not excluded by any rule (e.g., hearsay, privilege).', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['relevance', 'materiality', 'competence', 'exclusionary rule', 'foundation'], sources: ['Fed. R. Evid. 401-403'] },
	{ term: 'Privilege', definition: 'A legal right that protects certain communications from being disclosed in court. Common privileges include attorney-client, doctor-patient, spousal, and clergy-penitent.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['attorney-client privilege', 'work product', 'waiver', 'Fifth Amendment'], sources: ['Fed. R. Evid. 501-502'] },
	{ term: 'Best Evidence Rule', definition: 'A rule requiring that the original of a writing, recording, or photograph be produced to prove its content, unless the original is unavailable through no fault of the proponent.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['original document', 'duplicate', 'secondary evidence', 'authentication'], sources: ['Fed. R. Evid. 1001-1008'] },
	{ term: 'Forensic Evidence', definition: 'Scientific evidence used in court proceedings, including DNA analysis, fingerprints, ballistics, toxicology, digital forensics, and trace evidence. Must meet Daubert or Frye reliability standards.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['DNA', 'fingerprints', 'ballistics', 'digital forensics', 'Daubert'], sources: ['Fed. R. Evid. 702'] },

	// ── Procedure ──
	{ term: 'Voir Dire', definition: 'The process by which prospective jurors are questioned by the judge and attorneys to determine their qualifications and suitability to serve on a jury. Challenges for cause and peremptory challenges may be exercised.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['jury selection', 'challenge for cause', 'peremptory challenge', 'Batson challenge'], sources: ["Black's Law Dictionary", 'Batson v. Kentucky, 476 U.S. 79 (1986)'] },
	{ term: 'Subpoena', definition: 'A court order compelling a person to appear and give testimony (subpoena ad testificandum) or to produce documents or other tangible evidence (subpoena duces tecum). Failure to comply may result in contempt.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['contempt', 'testimony', 'documents', 'compliance'], sources: ['Fed. R. Civ. P. 45', 'Fed. R. Crim. P. 17'] },
	{ term: 'Deposition', definition: 'A witness\'s sworn out-of-court testimony taken before trial as part of discovery. The testimony is recorded and may be used at trial if the witness is unavailable or for impeachment.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['discovery', 'interrogatory', 'sworn testimony', 'impeachment'], sources: ['Fed. R. Civ. P. 30-32'] },
	{ term: 'Discovery', definition: 'The pre-trial process by which each party obtains evidence and information from the opposing party through depositions, interrogatories, requests for production, and requests for admission.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['deposition', 'interrogatory', 'request for production', 'Brady material'], sources: ['Fed. R. Civ. P. 26-37', 'Brady v. Maryland'] },
	{ term: 'Summary Judgment', definition: 'A judgment entered by a court for one party against another without a full trial when there is no genuine dispute as to any material fact and the movant is entitled to judgment as a matter of law.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['motion', 'material fact', 'genuine dispute', 'judgment as a matter of law'], sources: ['Fed. R. Civ. P. 56'] },
	{ term: 'Motion to Suppress', definition: 'A request to exclude evidence from trial because it was obtained in violation of the defendant\'s constitutional rights, such as through an illegal search or coerced confession.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['exclusionary rule', 'fruit of the poisonous tree', 'Fourth Amendment', 'Miranda'], sources: ['Fed. R. Crim. P. 12(b)(3)', 'Mapp v. Ohio'] },
	{ term: 'Change of Venue', definition: 'The transfer of a case from one court or jurisdiction to another, typically requested when pretrial publicity or local prejudice makes it unlikely the defendant can receive a fair trial.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['venue', 'pretrial publicity', 'fair trial', 'impartial jury'], sources: ['Fed. R. Crim. P. 21'] },

	// ── Civil ──
	{ term: 'Tort', definition: 'A civil wrong, other than breach of contract, that causes harm or loss to another person and for which the injured party may seek damages. Includes negligence, intentional torts, and strict liability.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['negligence', 'damages', 'duty of care', 'proximate cause'], sources: ["Black's Law Dictionary", 'Restatement (Third) of Torts'] },
	{ term: 'Negligence', definition: 'Failure to exercise the degree of care that a reasonably prudent person would exercise under the same circumstances. Requires proof of duty, breach, causation, and damages.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['duty of care', 'breach', 'proximate cause', 'reasonable person', 'damages'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Torts §281'] },
	{ term: 'Strict Liability', definition: 'Liability imposed without proof of negligence or intent. Applied in cases involving abnormally dangerous activities, defective products, and certain statutory violations.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['product liability', 'ultrahazardous activity', 'no-fault', 'absolute liability'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Torts §402A'] },
	{ term: 'Fiduciary Duty', definition: 'A legal obligation of one party to act in the best interest of another, arising from a relationship of trust. Breaching fiduciary duty can result in civil liability.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['trust', 'loyalty', 'care', 'breach of fiduciary duty', 'self-dealing'], sources: ["Black's Law Dictionary"] },
	{ term: 'Breach of Contract', definition: 'A violation of a contractual obligation when a party fails to perform a duty or promise as agreed. Remedies include damages, specific performance, or rescission.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['contract', 'consideration', 'damages', 'specific performance', 'rescission'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Contracts'] },
	{ term: 'Injunction', definition: 'A court order requiring a party to do or refrain from doing a specific act. May be temporary, preliminary, or permanent. Requires showing of irreparable harm and likelihood of success on the merits.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['restraining order', 'equitable relief', 'irreparable harm', 'preliminary injunction'], sources: ['Fed. R. Civ. P. 65'] },
	{ term: 'Damages', definition: 'Monetary compensation awarded to a party who has suffered loss or harm due to the wrongful act of another. Types include compensatory, punitive, nominal, and liquidated damages.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['compensatory damages', 'punitive damages', 'nominal damages', 'restitution'], sources: ["Black's Law Dictionary"] },
	{ term: 'Statute of Limitations', definition: 'A law that sets the maximum time after an event within which legal proceedings may be initiated. Varies by type of claim and jurisdiction.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['tolling', 'accrual', 'repose', 'limitations period', 'laches'], sources: ["Black's Law Dictionary"] },

	// ── Cybercrime & Digital Privacy ──
	{ term: 'Protected Computer', definition: 'Under the CFAA (18 USC §1030), a computer exclusively for the use of a financial institution or the U.S. Government, or any computer used in or affecting interstate or foreign commerce or communication. Broadly interpreted to include virtually any internet-connected device.', category: 'cybercrime', jurisdiction: 'Federal', relatedTerms: ['CFAA', 'unauthorized access', 'exceeds authorized access', 'computer fraud'], sources: ['18 USC §1030(e)(2)', 'Van Buren v. United States, 593 U.S. 374 (2021)'] },
	{ term: 'Exceeds Authorized Access', definition: 'Under the CFAA, accessing a computer with authorization but using such access to obtain or alter information in the computer that the accessor is not entitled so to obtain or alter. The Supreme Court in Van Buren narrowed this to mean accessing areas of a computer one is not permitted to access, not misusing information one is permitted to access.', category: 'cybercrime', jurisdiction: 'Federal', relatedTerms: ['CFAA', 'unauthorized access', 'protected computer', 'Van Buren'], sources: ['18 USC §1030(e)(6)', 'Van Buren v. United States, 593 U.S. 374 (2021)'] },
	{ term: 'Electronic Communication', definition: 'Under ECPA, any transfer of signs, signals, writing, images, sounds, data, or intelligence of any nature transmitted in whole or in part by a wire, radio, electromagnetic, photoelectronic, or photooptical system that affects interstate or foreign commerce. Does not include wire or oral communications, or communications through a tone-only paging device.', category: 'cybercrime', jurisdiction: 'Federal', relatedTerms: ['Wiretap Act', 'Stored Communications Act', 'interception', 'electronic storage'], sources: ['18 USC §2510(12)'] },
	{ term: 'Protected Health Information (PHI)', definition: 'Under HIPAA, individually identifiable health information that is transmitted or maintained in any form or medium by a covered entity or its business associate. Includes demographic data, information relating to the physical or mental health of an individual, provision of health care, or payment for health care that identifies the individual or could reasonably be used to identify the individual.', category: 'regulatory', jurisdiction: 'Federal', relatedTerms: ['HIPAA', 'covered entity', 'business associate', 'de-identified data', 'minimum necessary'], sources: ['45 CFR §160.103'] },
	{ term: 'Personally Identifiable Information (PII)', definition: 'Information that can be used to distinguish or trace an individual\'s identity, either alone or when combined with other personal or identifying information. Includes name, SSN, date of birth, biometric records, and other data linkable to an individual. Various federal and state laws define PII differently.', category: 'regulatory', jurisdiction: 'Federal/State', relatedTerms: ['PHI', 'CCPA', 'data breach', 'privacy', 'de-identification'], sources: ['OMB M-07-16', 'NIST SP 800-122'] },
	{ term: 'Trade Secret', definition: 'Information, including a formula, pattern, compilation, program, device, method, technique, or process, that derives independent economic value from not being generally known to or readily ascertainable by other persons who can obtain economic value from its disclosure or use, and is the subject of efforts that are reasonable under the circumstances to maintain its secrecy.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['Economic Espionage Act', 'DTSA', 'misappropriation', 'non-disclosure', 'non-compete'], sources: ['18 USC §1839(3)', 'Uniform Trade Secrets Act'] },
	{ term: 'Qui Tam', definition: 'A provision of the False Claims Act allowing a private individual (relator or whistleblower) to file a lawsuit on behalf of the United States Government against a person or entity that has defrauded the government. The relator may receive 15-30% of the recovery. The government may choose to intervene and take over the case.', category: 'civil', jurisdiction: 'Federal', relatedTerms: ['False Claims Act', 'whistleblower', 'relator', 'fraud', 'treble damages'], sources: ['31 USC §3730'] },

	// ── General Legal ──
	{ term: 'Stare Decisis', definition: 'The doctrine that courts should follow precedents set by prior decisions when the same points arise again in litigation. Promotes consistency, predictability, and stability in the law.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['precedent', 'binding authority', 'persuasive authority', 'overrule'], sources: ["Black's Law Dictionary"] },
	{ term: 'Res Judicata', definition: 'A matter that has been adjudicated by a competent court and may not be pursued further by the same parties. Prevents relitigation of claims that were or could have been raised.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['claim preclusion', 'issue preclusion', 'collateral estoppel', 'final judgment'], sources: ["Black's Law Dictionary"] },
	{ term: 'Pro Bono', definition: 'Legal work performed voluntarily and without payment, typically for individuals who cannot afford legal representation. Many bar associations establish pro bono requirements or expectations.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['legal aid', 'indigent defense', 'public defender', 'access to justice'], sources: ["Black's Law Dictionary", 'ABA Model Rule 6.1'] },
	{ term: 'Amicus Curiae', definition: 'A "friend of the court" — a person or organization not party to a case who offers information, expertise, or insight to assist the court in deciding a matter. Common in appellate and Supreme Court cases.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['brief', 'appellate', 'intervention', 'interest group'], sources: ['Fed. R. App. P. 29', "Black's Law Dictionary"] },
	{ term: 'Certiorari', definition: 'A writ issued by a higher court directing a lower court to transmit the record of a case for review. The primary method by which the U.S. Supreme Court selects cases for review.', category: 'general', jurisdiction: 'Federal', relatedTerms: ['Supreme Court', 'writ', 'petition', 'appeal', 'rule of four'], sources: ['28 USC §1254', "Black's Law Dictionary"] },
	{ term: 'Ex Parte', definition: 'A proceeding brought by one party without notice to the other. Ex parte communications with a judge are generally prohibited, but ex parte motions may be granted in emergency situations.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['unilateral', 'temporary restraining order', 'emergency motion'], sources: ["Black's Law Dictionary"] },
	{ term: 'Jurisdiction', definition: 'The authority of a court to hear and decide a case. Includes subject matter jurisdiction (types of cases), personal jurisdiction (authority over parties), and territorial jurisdiction.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['venue', 'standing', 'subject matter', 'personal jurisdiction', 'diversity'], sources: ["Black's Law Dictionary", '28 USC §1331-1332'] },
	{ term: 'Precedent', definition: 'A court decision that serves as an authority for deciding subsequent similar cases. Binding precedent must be followed by lower courts in the same jurisdiction; persuasive precedent may be considered but is not binding.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['stare decisis', 'binding authority', 'persuasive authority', 'distinguish', 'overrule'], sources: ["Black's Law Dictionary"] },

	// ── Additional Criminal ──
	{ term: 'Conspiracy', definition: 'An agreement between two or more persons to commit an unlawful act, combined with an overt act in furtherance of the agreement. Each conspirator is liable for the foreseeable acts of co-conspirators committed in furtherance of the conspiracy.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['RICO', 'overt act', 'co-conspirator', 'Pinkerton doctrine'], sources: ['18 USC §371', "Black's Law Dictionary"] },
	{ term: 'Solicitation', definition: 'The act of requesting, encouraging, or commanding another person to commit a crime. The offense is complete upon the asking, regardless of whether the solicited crime is actually committed.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['conspiracy', 'attempt', 'incitement', 'aiding and abetting'], sources: ['Model Penal Code §5.02', "Black's Law Dictionary"] },
	{ term: 'Criminal Attempt', definition: 'An act done with the intent to commit a crime that goes beyond mere preparation but falls short of actual commission. Requires specific intent and a substantial step toward completion of the crime.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['mens rea', 'substantial step', 'impossibility', 'abandonment'], sources: ['Model Penal Code §5.01', "Black's Law Dictionary"] },
	{ term: 'Larceny', definition: 'The unlawful taking and carrying away of the personal property of another with the intent to permanently deprive the owner of possession. Distinguished from robbery by the absence of force or intimidation.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['theft', 'robbery', 'embezzlement', 'grand theft', 'petty theft'], sources: ["Black's Law Dictionary"] },
	{ term: 'Perjury', definition: 'The willful giving of false testimony under oath or affirmation in a judicial or official proceeding on a matter material to the proceeding. Requires knowledge that the statement is false.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['false statement', 'oath', 'subornation of perjury', 'materiality'], sources: ['18 USC §1621', "Black's Law Dictionary"] },
	{ term: 'Contempt of Court', definition: 'Willful disobedience of a court order or disruptive behavior in the courtroom that obstructs the administration of justice. Civil contempt coerces compliance; criminal contempt punishes past misconduct.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['court order', 'sanctions', 'civil contempt', 'criminal contempt'], sources: ['18 USC §401', "Black's Law Dictionary"] },
	{ term: 'Extortion', definition: 'Obtaining property or compelling action from another through wrongful use of force, fear, threats, or abuse of official authority. Distinguished from robbery by the nature of the threat and timing.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['blackmail', 'coercion', 'Hobbs Act', 'threats'], sources: ['18 USC §1951', "Black's Law Dictionary"] },
	{ term: 'Kidnapping', definition: 'The unlawful seizure, transportation, and confinement of a person against their will. Aggravated kidnapping involves ransom demands, bodily harm, or use of a deadly weapon.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['false imprisonment', 'abduction', 'ransom', 'custodial interference'], sources: ['18 USC §1201', "Black's Law Dictionary"] },
	{ term: 'Money Laundering', definition: 'The process of making illegally obtained money appear legitimate by channeling it through legal businesses or financial transactions. Federal law criminalizes conducting financial transactions with proceeds of specified unlawful activity.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['Bank Secrecy Act', 'structuring', 'smurfing', 'proceeds', 'RICO'], sources: ['18 USC §1956-1957', "Black's Law Dictionary"] },
	{ term: 'Aggravated Assault', definition: 'An assault committed with the intent to cause serious bodily harm or with the use of a deadly weapon. More serious than simple assault, typically classified as a felony with enhanced penalties.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['battery', 'deadly weapon', 'bodily harm', 'assault'], sources: ["Black's Law Dictionary", 'Model Penal Code §211.1'] },
	{ term: 'Stalking', definition: 'A pattern of repeated and unwanted attention, harassment, contact, or conduct directed at a specific person that would cause a reasonable person to feel fear for their safety or the safety of others.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['harassment', 'restraining order', 'cyberstalking', 'protective order'], sources: ['18 USC §2261A', "Black's Law Dictionary"] },
	{ term: 'Accessory', definition: 'A person who aids or contributes to the commission of a crime without being present at the scene. An accessory before the fact assists in planning; an accessory after the fact helps conceal the crime or the criminal.', category: 'criminal', jurisdiction: 'Federal/State', relatedTerms: ['accomplice', 'aiding and abetting', 'principal', 'harboring'], sources: ['18 USC §3', "Black's Law Dictionary"] },

	// ── Additional Constitutional ──
	{ term: 'Eminent Domain', definition: 'The power of the government to take private property for public use, provided the owner receives just compensation as required by the Fifth Amendment. The taking must serve a legitimate public purpose.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['just compensation', 'condemnation', 'taking', 'public use', 'inverse condemnation'], sources: ['U.S. Const. Amend. V', 'Kelo v. City of New London, 545 U.S. 469 (2005)'] },
	{ term: 'Commerce Clause', definition: 'Article I, Section 8 of the Constitution granting Congress the power to regulate commerce among the states, with foreign nations, and with Indian tribes. Broadly interpreted to give Congress extensive regulatory authority over interstate economic activity.', category: 'constitutional', jurisdiction: 'Federal', relatedTerms: ['interstate commerce', 'dormant commerce clause', 'Necessary and Proper Clause', 'federal power'], sources: ['U.S. Const. Art. I, §8, cl. 3', 'Wickard v. Filburn, 317 U.S. 111 (1942)'] },
	{ term: 'Establishment Clause', definition: 'The First Amendment prohibition against the government establishing an official religion or unduly favoring one religion over another. Requires government neutrality toward religion and separation of church and state.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Free Exercise Clause', 'separation of church and state', 'Lemon test', 'endorsement test'], sources: ['U.S. Const. Amend. I', 'Lemon v. Kurtzman, 403 U.S. 602 (1971)'] },
	{ term: 'Free Exercise Clause', definition: 'The First Amendment protection of the right to practice religion freely without government interference. The government may not target religious practices for restriction but may enforce neutral, generally applicable laws that incidentally burden religion.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Establishment Clause', 'religious freedom', 'strict scrutiny', 'RFRA'], sources: ['U.S. Const. Amend. I', 'Employment Division v. Smith, 494 U.S. 872 (1990)'] },
	{ term: 'Incorporation Doctrine', definition: 'The constitutional principle by which selected provisions of the Bill of Rights are made applicable to the states through the Due Process Clause of the Fourteenth Amendment. Most but not all Bill of Rights protections have been incorporated.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Fourteenth Amendment', 'selective incorporation', 'due process', 'Bill of Rights'], sources: ['U.S. Const. Amend. XIV', 'McDonald v. City of Chicago, 561 U.S. 742 (2010)'] },
	{ term: 'Sovereign Immunity', definition: 'The legal doctrine that the government cannot be sued without its consent. The federal government has partially waived sovereign immunity through statutes like the Federal Tort Claims Act. States retain sovereign immunity under the Eleventh Amendment.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['Eleventh Amendment', 'FTCA', 'qualified immunity', 'Section 1983'], sources: ['U.S. Const. Amend. XI', "Black's Law Dictionary"] },
	{ term: 'Separation of Powers', definition: 'The constitutional principle dividing government authority among three branches — legislative, executive, and judicial — to prevent concentration of power and provide checks and balances.', category: 'constitutional', jurisdiction: 'Federal/State', relatedTerms: ['checks and balances', 'executive power', 'legislative power', 'judicial power'], sources: ['U.S. Const. Art. I-III', "Black's Law Dictionary"] },
	{ term: 'Supremacy Clause', definition: 'Article VI, Clause 2 of the Constitution establishing that the Constitution, federal laws, and treaties are the supreme law of the land, prevailing over conflicting state laws through the doctrine of federal preemption.', category: 'constitutional', jurisdiction: 'Federal', relatedTerms: ['preemption', 'federalism', 'federal law', 'conflict of laws'], sources: ['U.S. Const. Art. VI, cl. 2', "Black's Law Dictionary"] },

	// ── Additional Evidence ──
	{ term: 'Authentication', definition: 'The process of establishing that evidence is what its proponent claims it to be. Requires sufficient evidence to support a finding that the item is genuine, which may include testimony, distinctive characteristics, or chain of custody.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['chain of custody', 'foundation', 'best evidence rule', 'identification'], sources: ['Fed. R. Evid. 901-902'] },
	{ term: 'Impeachment', definition: 'The process of attacking the credibility of a witness through prior inconsistent statements, bias, character for untruthfulness, contradiction, or showing defects in perception, memory, or ability to communicate.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['credibility', 'prior inconsistent statement', 'bias', 'rehabilitation'], sources: ['Fed. R. Evid. 607-613'] },
	{ term: 'Judicial Notice', definition: 'A court\'s acceptance of a fact as true without requiring formal proof because the fact is either generally known within the court\'s jurisdiction or can be accurately and readily determined from sources whose accuracy cannot be questioned.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['adjudicative facts', 'legislative facts', 'common knowledge'], sources: ['Fed. R. Evid. 201'] },
	{ term: 'Relevance', definition: 'Evidence is relevant if it has any tendency to make a fact of consequence more or less probable than it would be without the evidence. All relevant evidence is admissible unless excluded by a specific rule, statute, or constitutional provision.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['materiality', 'probative value', 'prejudicial effect', 'Rule 403'], sources: ['Fed. R. Evid. 401-403'] },
	{ term: 'Spoliation', definition: 'The intentional, reckless, or negligent destruction, alteration, or concealment of evidence relevant to litigation. May result in adverse inference instructions, sanctions, or separate tort liability.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['preservation', 'litigation hold', 'sanctions', 'adverse inference'], sources: ['Fed. R. Civ. P. 37(e)', "Black's Law Dictionary"] },
	{ term: 'Work Product Doctrine', definition: 'Protection from discovery of documents and tangible things prepared in anticipation of litigation or for trial by or for a party or representative. Provides qualified immunity from discovery, with stronger protection for opinion work product.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['attorney-client privilege', 'discovery', 'anticipation of litigation', 'mental impressions'], sources: ['Fed. R. Civ. P. 26(b)(3)', 'Hickman v. Taylor, 329 U.S. 495 (1947)'] },
	{ term: 'Foundation', definition: 'The preliminary evidence necessary to establish the admissibility of other evidence. A proper foundation demonstrates the relevance, authenticity, and reliability of the evidence being offered.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['authentication', 'laying a foundation', 'admissibility', 'preliminary questions'], sources: ['Fed. R. Evid. 104, 901'] },
	{ term: 'Protective Order', definition: 'A court order restricting the disclosure or use of discovery materials or evidence to protect confidential information, trade secrets, privacy interests, or national security. May limit who can view materials and how they are handled.', category: 'evidence', jurisdiction: 'Federal/State', relatedTerms: ['discovery', 'confidentiality', 'trade secrets', 'sealing'], sources: ['Fed. R. Civ. P. 26(c)'] },

	// ── Additional Procedure ──
	{ term: 'Continuance', definition: 'The postponement or adjournment of a court proceeding to a later date. Granted at the court\'s discretion for good cause such as illness, unavailability of counsel or witnesses, or need for additional preparation.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['adjournment', 'postponement', 'speedy trial', 'good cause'], sources: ["Black's Law Dictionary"] },
	{ term: 'Default Judgment', definition: 'A judgment entered against a party who has failed to respond to a complaint, motion, or court order within the required time. May be set aside upon showing of good cause, excusable neglect, or meritorious defense.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['failure to appear', 'set aside', 'excusable neglect', 'service of process'], sources: ['Fed. R. Civ. P. 55'] },
	{ term: 'Demurrer', definition: 'A formal objection that the opposing party\'s pleading is legally insufficient even if all facts alleged are true. Used in some state courts; equivalent to a motion to dismiss for failure to state a claim in federal court.', category: 'procedure', jurisdiction: 'State', relatedTerms: ['motion to dismiss', 'failure to state a claim', 'pleading', '12(b)(6)'], sources: ['CA Code Civ. Proc. §430.10', "Black's Law Dictionary"] },
	{ term: 'Interlocutory Appeal', definition: 'An appeal of a non-final order or ruling before the conclusion of the trial. Generally disfavored but permitted for certain orders such as injunctions, class certification, or orders involving controlling questions of law.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['final judgment rule', 'collateral order doctrine', 'mandamus', 'certification'], sources: ['28 USC §1292', "Black's Law Dictionary"] },
	{ term: 'Mandamus', definition: 'An extraordinary writ issued by a higher court commanding a lower court or government official to perform a mandatory or ministerial duty. Available only when there is a clear legal right and no other adequate remedy.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['writ', 'extraordinary remedy', 'ministerial duty', 'discretionary act'], sources: ['28 USC §1651', "Black's Law Dictionary"] },
	{ term: 'Preliminary Hearing', definition: 'A court proceeding held to determine whether there is probable cause to believe a crime was committed and the defendant committed it. Less rigorous than a trial; the prosecution need only show probable cause, not proof beyond a reasonable doubt.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['probable cause', 'grand jury', 'arraignment', 'bindover'], sources: ['Fed. R. Crim. P. 5.1'] },
	{ term: 'Mistrial', definition: 'A trial that is terminated and declared void before the jury returns a verdict, due to a fundamental error, misconduct, hung jury, or other circumstance that would make a fair verdict impossible. Generally allows retrial without double jeopardy.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['hung jury', 'manifest necessity', 'double jeopardy', 'new trial'], sources: ["Black's Law Dictionary"] },
	{ term: 'Joinder', definition: 'The combining of multiple parties or claims in a single lawsuit. Permissive joinder allows parties with common questions of law or fact; compulsory joinder requires inclusion of parties necessary for complete relief.', category: 'procedure', jurisdiction: 'Federal/State', relatedTerms: ['consolidation', 'severance', 'necessary parties', 'permissive joinder'], sources: ['Fed. R. Civ. P. 18-20'] },

	// ── Additional Civil ──
	{ term: 'Class Action', definition: 'A lawsuit in which one or more plaintiffs bring a claim on behalf of a larger group of similarly situated persons. Requires numerosity, commonality, typicality, and adequacy of representation. The class must be certified by the court.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['certification', 'opt-out', 'settlement', 'numerosity', 'commonality'], sources: ['Fed. R. Civ. P. 23'] },
	{ term: 'Contribution', definition: 'The right of a tortfeasor who has paid more than their proportionate share of liability to recover the excess from other joint tortfeasors. Distributes the burden of liability among those responsible.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['joint and several liability', 'indemnification', 'comparative fault', 'apportionment'], sources: ["Black's Law Dictionary", 'Uniform Contribution Among Tortfeasors Act'] },
	{ term: 'Indemnification', definition: 'An obligation by one party to compensate another party for losses or damages. Distinguished from contribution in that it shifts the entire loss rather than proportionally sharing it. May arise from contract, statute, or equitable principles.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['hold harmless', 'contribution', 'insurance', 'reimbursement'], sources: ["Black's Law Dictionary"] },
	{ term: 'Vicarious Liability', definition: 'Legal responsibility imposed on one party for the wrongful acts of another based on the relationship between them. Most commonly applied through respondeat superior, making employers liable for employee acts within the scope of employment.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['respondeat superior', 'agency', 'scope of employment', 'independent contractor'], sources: ["Black's Law Dictionary", 'Restatement (Third) of Agency'] },
	{ term: 'Wrongful Death', definition: 'A civil cause of action brought by the surviving family members or estate of a person whose death was caused by the wrongful act, neglect, or default of another. Allows recovery of damages including lost earnings, loss of companionship, and funeral expenses.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['survival action', 'beneficiaries', 'loss of consortium', 'pecuniary damages'], sources: ["Black's Law Dictionary", '42 USC §1983'] },
	{ term: 'Products Liability', definition: 'The legal liability of manufacturers, distributors, and sellers for injuries caused by defective products. May be based on negligence, strict liability, or breach of warranty. Defects include manufacturing, design, and failure to warn.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['strict liability', 'manufacturing defect', 'design defect', 'failure to warn', 'warranty'], sources: ['Restatement (Third) of Torts: Products Liability'] },
	{ term: 'Nuisance', definition: 'An unreasonable interference with the use and enjoyment of land (private nuisance) or with rights common to the general public (public nuisance). Remedies include injunction, damages, and abatement.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['trespass', 'injunction', 'abatement', 'unreasonable interference'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Torts §821A-D'] },
	{ term: 'Trespass', definition: 'An unauthorized intentional entry onto or interference with the property of another. Includes trespass to land, trespass to chattels (personal property), and trespass to the person (assault/battery).', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['nuisance', 'ejectment', 'conversion', 'unauthorized entry'], sources: ["Black's Law Dictionary"] },
	{ term: 'Malpractice', definition: 'Professional negligence or misconduct by a professional such as a physician, attorney, or accountant that falls below the accepted standard of care and causes harm to a client or patient.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['negligence', 'standard of care', 'professional liability', 'informed consent'], sources: ["Black's Law Dictionary"] },
	{ term: 'Conversion', definition: 'The wrongful exercise of dominion or control over another\'s personal property in a manner inconsistent with the owner\'s rights. The civil equivalent of theft, allowing recovery of the property\'s full value.', category: 'civil', jurisdiction: 'Federal/State', relatedTerms: ['trespass to chattels', 'theft', 'replevin', 'trover'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Torts §222A'] },

	// ── Additional General ──
	{ term: 'Standing', definition: 'The legal right of a party to bring a lawsuit. Requires showing an injury in fact that is concrete and particularized, a causal connection between the injury and the conduct complained of, and likelihood that the injury will be redressed by a favorable decision.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['case or controversy', 'injury in fact', 'ripeness', 'mootness'], sources: ['U.S. Const. Art. III', 'Lujan v. Defenders of Wildlife, 504 U.S. 555 (1992)'] },
	{ term: 'Mootness', definition: 'A doctrine requiring dismissal of a case when the issues presented are no longer live or the parties lack a legally cognizable interest in the outcome. An exception exists for controversies capable of repetition yet evading review.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['standing', 'case or controversy', 'ripeness', 'capable of repetition'], sources: ["Black's Law Dictionary"] },
	{ term: 'Ripeness', definition: 'A justiciability doctrine requiring that a case present a sufficiently developed controversy suitable for judicial resolution. Courts will not issue advisory opinions on hypothetical disputes that have not yet materialized.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['standing', 'mootness', 'justiciability', 'advisory opinion'], sources: ["Black's Law Dictionary"] },
	{ term: 'Comity', definition: 'A principle of mutual respect whereby courts of one jurisdiction give effect to the laws and judicial decisions of another jurisdiction, not as a matter of obligation but out of deference and goodwill.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['full faith and credit', 'conflict of laws', 'forum selection', 'choice of law'], sources: ["Black's Law Dictionary"] },
	{ term: 'Recusal', definition: 'The disqualification or voluntary withdrawal of a judge from a case due to a conflict of interest, bias, or appearance of impropriety. Federal judges must recuse when their impartiality might reasonably be questioned.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['disqualification', 'bias', 'conflict of interest', 'impartiality'], sources: ['28 USC §455', "Black's Law Dictionary"] },
	{ term: 'Nolo Contendere', definition: 'A plea of no contest in which the defendant neither admits nor denies the charges but accepts punishment. Unlike a guilty plea, it generally cannot be used as an admission of guilt in subsequent civil proceedings.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['guilty plea', 'plea bargain', 'Alford plea', 'sentencing'], sources: ['Fed. R. Crim. P. 11', "Black's Law Dictionary"] },
	{ term: 'Nolle Prosequi', definition: 'A formal declaration by the prosecution that it is abandoning or declining to pursue a criminal case. Does not constitute an acquittal and generally does not prevent future prosecution for the same offense.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['dismissal', 'prosecution', 'double jeopardy', 'discretion'], sources: ["Black's Law Dictionary"] },
	{ term: 'Sua Sponte', definition: 'An action taken by the court on its own initiative without a motion or request from either party. Courts may raise jurisdictional issues, dismiss frivolous cases, or address procedural defects sua sponte.', category: 'general', jurisdiction: 'Federal/State', relatedTerms: ['court discretion', 'motion', 'jurisdiction', 'judicial authority'], sources: ["Black's Law Dictionary"] },

	// ── Family Law ──
	{ term: 'Alimony', definition: 'Court-ordered financial support paid by one spouse to the other during or after divorce. Also called spousal support or maintenance. Factors include length of marriage, earning capacity, standard of living, and contributions to the marriage.', category: 'family', jurisdiction: 'State', relatedTerms: ['spousal support', 'maintenance', 'divorce', 'marital property'], sources: ["Black's Law Dictionary"] },
	{ term: 'Child Custody', definition: 'The legal determination of which parent or guardian will have physical care and legal decision-making authority for a minor child. Types include sole custody, joint custody, physical custody, and legal custody. Determined by the best interest of the child standard.', category: 'family', jurisdiction: 'State', relatedTerms: ['best interest of the child', 'visitation', 'joint custody', 'sole custody', 'parenting plan'], sources: ["Black's Law Dictionary", 'Uniform Child Custody Jurisdiction Act'] },
	{ term: 'Child Support', definition: 'A periodic payment made by a non-custodial parent to the custodial parent for the financial support of their child. Amounts are typically calculated using state guidelines based on parental income, number of children, and custody arrangement.', category: 'family', jurisdiction: 'State', relatedTerms: ['custody', 'income shares model', 'modification', 'enforcement', 'arrearage'], sources: ['42 USC §651-669b', "Black's Law Dictionary"] },
	{ term: 'Adoption', definition: 'The legal process by which a person assumes the parenting rights and responsibilities of a child from the biological parents. Creates a permanent parent-child relationship with all attendant legal rights, including inheritance.', category: 'family', jurisdiction: 'State', relatedTerms: ['termination of parental rights', 'foster care', 'consent', 'home study', 'open adoption'], sources: ["Black's Law Dictionary", 'Uniform Adoption Act'] },
	{ term: 'Guardianship', definition: 'A legal relationship in which a court appoints an individual to make personal, medical, or financial decisions for a minor or an incapacitated adult who cannot care for themselves. May be limited or plenary.', category: 'family', jurisdiction: 'State', relatedTerms: ['conservatorship', 'ward', 'incapacity', 'minor', 'fiduciary'], sources: ["Black's Law Dictionary", 'Uniform Guardianship Act'] },
	{ term: 'Paternity', definition: 'The legal determination of fatherhood. May be established through voluntary acknowledgment, genetic testing, or court order. Establishing paternity confers rights and obligations including custody, visitation, and child support.', category: 'family', jurisdiction: 'State', relatedTerms: ['DNA testing', 'acknowledgment', 'presumed father', 'child support'], sources: ["Black's Law Dictionary", 'Uniform Parentage Act'] },
	{ term: 'Prenuptial Agreement', definition: 'A contract entered into before marriage that defines each spouse\'s property rights, financial obligations, and division of assets in the event of divorce or death. Must be entered voluntarily with full financial disclosure.', category: 'family', jurisdiction: 'State', relatedTerms: ['postnuptial agreement', 'marital property', 'separate property', 'unconscionability'], sources: ["Black's Law Dictionary", 'Uniform Premarital Agreement Act'] },
	{ term: 'Dissolution of Marriage', definition: 'The legal termination of a marriage by court decree, commonly known as divorce. Addresses property division, spousal support, child custody, child support, and debt allocation. Most states offer no-fault dissolution.', category: 'family', jurisdiction: 'State', relatedTerms: ['divorce', 'separation', 'annulment', 'property division', 'no-fault'], sources: ["Black's Law Dictionary"] },
	{ term: 'Emancipation', definition: 'The legal process by which a minor is freed from the control of parents or guardians and is given the legal rights and responsibilities of an adult before reaching the age of majority.', category: 'family', jurisdiction: 'State', relatedTerms: ['minor', 'age of majority', 'parental rights', 'independence'], sources: ["Black's Law Dictionary"] },
	{ term: 'Restraining Order', definition: 'A court order prohibiting a person from contacting, approaching, or harassing another person. In family law, commonly issued in cases of domestic violence. May be temporary (ex parte) or permanent after a hearing.', category: 'family', jurisdiction: 'State', relatedTerms: ['protective order', 'domestic violence', 'injunction', 'no-contact order'], sources: ["Black's Law Dictionary"] },
	{ term: 'Community Property', definition: 'A system of marital property ownership used in some states in which most property acquired during marriage is owned equally by both spouses regardless of which spouse earned or acquired it. Contrasted with equitable distribution.', category: 'family', jurisdiction: 'State', relatedTerms: ['separate property', 'equitable distribution', 'marital property', 'transmutation'], sources: ["Black's Law Dictionary"] },
	{ term: 'Legal Separation', definition: 'A court-ordered arrangement in which a married couple lives apart while remaining legally married. Addresses property, support, and custody issues without terminating the marriage, preserving certain benefits.', category: 'family', jurisdiction: 'State', relatedTerms: ['dissolution', 'divorce', 'separation agreement', 'reconciliation'], sources: ["Black's Law Dictionary"] },
	{ term: 'Annulment', definition: 'A court declaration that a marriage is void or voidable, treating it as though it never existed. Grounds include fraud, duress, incapacity, bigamy, underage marriage, or consanguinity.', category: 'family', jurisdiction: 'State', relatedTerms: ['void marriage', 'voidable marriage', 'fraud', 'bigamy', 'dissolution'], sources: ["Black's Law Dictionary"] },
	{ term: 'Visitation Rights', definition: 'The legal right of a non-custodial parent or other person to spend time with a child according to a court-ordered schedule. May be supervised, unsupervised, or virtual depending on the circumstances.', category: 'family', jurisdiction: 'State', relatedTerms: ['custody', 'parenting time', 'best interest of the child', 'supervised visitation'], sources: ["Black's Law Dictionary"] },

	// ── Property Law ──
	{ term: 'Easement', definition: 'A nonpossessory interest in another\'s land that entitles the holder to use the land for a specific purpose. Types include appurtenant (benefits adjacent land), in gross (benefits a person), prescriptive (acquired through continuous use), and by necessity.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['servitude', 'right of way', 'prescriptive easement', 'license', 'encumbrance'], sources: ["Black's Law Dictionary", 'Restatement (Third) of Property: Servitudes'] },
	{ term: 'Lien', definition: 'A legal claim or encumbrance on property as security for payment of a debt or obligation. Types include mortgage liens, mechanic\'s liens, tax liens, and judgment liens. Priority is generally determined by order of recording.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['mortgage', 'encumbrance', 'priority', 'foreclosure', 'judgment lien'], sources: ["Black's Law Dictionary"] },
	{ term: 'Mortgage', definition: 'A security interest in real property given by the borrower to the lender as collateral for a loan. The lender holds a lien on the property until the loan is paid in full. Default may lead to foreclosure.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['deed of trust', 'foreclosure', 'lien', 'refinancing', 'amortization'], sources: ["Black's Law Dictionary"] },
	{ term: 'Deed', definition: 'A written legal document that transfers ownership of real property from one party to another. Types include warranty deed (full guarantees), grant deed (limited guarantees), and quitclaim deed (no guarantees). Must be signed, delivered, and accepted.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['title', 'conveyance', 'warranty deed', 'quitclaim deed', 'recording'], sources: ["Black's Law Dictionary"] },
	{ term: 'Title', definition: 'The legal right of ownership to real or personal property, including the right to possess, use, enjoy, and dispose of it. Title may be held individually, jointly, in common, or in trust. Title searches verify ownership and encumbrances.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['deed', 'chain of title', 'title insurance', 'clear title', 'cloud on title'], sources: ["Black's Law Dictionary"] },
	{ term: 'Adverse Possession', definition: 'A method of acquiring title to real property by open, notorious, continuous, hostile, and exclusive possession for a statutory period. The possessor must treat the property as their own without the owner\'s permission.', category: 'property', jurisdiction: 'State', relatedTerms: ['statute of limitations', 'hostile possession', 'tacking', 'color of title'], sources: ["Black's Law Dictionary"] },
	{ term: 'Covenant', definition: 'A promise or agreement relating to the use or condition of real property, typically contained in a deed or recorded document. Restrictive covenants limit property use; affirmative covenants require specific actions. May run with the land.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['deed restriction', 'CC&Rs', 'equitable servitude', 'running with the land'], sources: ["Black's Law Dictionary"] },
	{ term: 'Zoning', definition: 'Government regulation dividing land into zones or districts with specific permitted uses such as residential, commercial, industrial, or agricultural. Zoning laws control building height, density, setbacks, and land use to promote orderly development.', category: 'property', jurisdiction: 'State/Local', relatedTerms: ['variance', 'conditional use permit', 'nonconforming use', 'comprehensive plan'], sources: ["Black's Law Dictionary", 'Village of Euclid v. Ambler Realty, 272 U.S. 365 (1926)'] },
	{ term: 'Encumbrance', definition: 'Any claim, lien, charge, or liability attached to real property that may diminish its value or affect its transferability. Includes mortgages, easements, liens, restrictions, and encroachments.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['lien', 'easement', 'mortgage', 'title search', 'clear title'], sources: ["Black's Law Dictionary"] },
	{ term: 'Quitclaim Deed', definition: 'A deed that conveys whatever interest the grantor may have in a property without making any warranties or guarantees about the quality of the title. Commonly used in family transfers, divorce, and clearing title defects.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['warranty deed', 'grant deed', 'title', 'conveyance'], sources: ["Black's Law Dictionary"] },
	{ term: 'Quiet Title', definition: 'A legal action to establish a party\'s title to real property against adverse claims and to remove clouds on title. Used to resolve disputes about ownership, boundary lines, or the validity of liens and encumbrances.', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['cloud on title', 'adverse possession', 'chain of title', 'marketable title'], sources: ["Black's Law Dictionary"] },
	{ term: 'Homestead Exemption', definition: 'A legal protection that shields a portion of a homeowner\'s equity in their primary residence from creditors in bankruptcy or judgment enforcement. Amounts and requirements vary significantly by state.', category: 'property', jurisdiction: 'State', relatedTerms: ['bankruptcy', 'exemption', 'creditor protection', 'primary residence'], sources: ["Black's Law Dictionary"] },
	{ term: 'Foreclosure', definition: 'The legal process by which a lender takes possession of property used as collateral when the borrower defaults on their mortgage. May be judicial (through court) or non-judicial (through power of sale clause in the deed of trust).', category: 'property', jurisdiction: 'Federal/State', relatedTerms: ['mortgage', 'default', 'deed of trust', 'right of redemption', 'deficiency judgment'], sources: ["Black's Law Dictionary"] },
	{ term: 'Landlord-Tenant Law', definition: 'The body of law governing the rights and obligations of landlords and tenants in residential and commercial leases. Covers lease terms, security deposits, habitability, eviction procedures, and tenant protections.', category: 'property', jurisdiction: 'State', relatedTerms: ['lease', 'eviction', 'habitability', 'security deposit', 'rent control'], sources: ["Black's Law Dictionary", 'Uniform Residential Landlord and Tenant Act'] },

	// ── Corporate & Business Law ──
	{ term: 'Corporation', definition: 'A legal entity separate from its owners (shareholders) that has its own rights, privileges, and liabilities. Provides limited liability protection, perpetual existence, and centralized management through a board of directors.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['shareholder', 'board of directors', 'limited liability', 'articles of incorporation', 'bylaws'], sources: ["Black's Law Dictionary"] },
	{ term: 'Limited Liability Company', definition: 'A business entity combining the limited liability protection of a corporation with the pass-through taxation and management flexibility of a partnership. Members are not personally liable for the company\'s debts or obligations.', category: 'corporate', jurisdiction: 'State', relatedTerms: ['operating agreement', 'member', 'manager', 'pass-through taxation', 'limited liability'], sources: ["Black's Law Dictionary", 'Uniform Limited Liability Company Act'] },
	{ term: 'Partnership', definition: 'An association of two or more persons to carry on a business for profit as co-owners. General partners share management and unlimited liability; limited partners contribute capital but have limited involvement and liability.', category: 'corporate', jurisdiction: 'State', relatedTerms: ['general partnership', 'limited partnership', 'LLP', 'joint venture', 'fiduciary duty'], sources: ["Black's Law Dictionary", 'Uniform Partnership Act'] },
	{ term: 'Securities Fraud', definition: 'Deceptive practices in the securities markets, including making false statements, omitting material facts, insider trading, and market manipulation. Violations of SEC Rule 10b-5 are the most common basis for securities fraud claims.', category: 'corporate', jurisdiction: 'Federal', relatedTerms: ['insider trading', 'Rule 10b-5', 'material misrepresentation', 'SEC', 'scienter'], sources: ['15 USC §78j(b)', 'SEC Rule 10b-5'] },
	{ term: 'Insider Trading', definition: 'The buying or selling of securities based on material, nonpublic information in breach of a fiduciary duty or relationship of trust. Illegal under federal securities law and subject to civil and criminal penalties.', category: 'corporate', jurisdiction: 'Federal', relatedTerms: ['securities fraud', 'material nonpublic information', 'tipping', 'SEC', '10b-5'], sources: ['15 USC §78j(b)', 'SEC v. Texas Gulf Sulphur Co., 401 F.2d 833 (1968)'] },
	{ term: 'Shareholder', definition: 'An owner of shares of stock in a corporation. Shareholders have rights including voting on major corporate decisions, receiving dividends, inspecting corporate records, and bringing derivative actions on behalf of the corporation.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['stockholder', 'common stock', 'preferred stock', 'dividend', 'proxy'], sources: ["Black's Law Dictionary"] },
	{ term: 'Merger', definition: 'The combination of two or more companies into a single entity. In a statutory merger, one company absorbs the other; in a consolidation, a new entity is created. Must be approved by boards of directors and shareholders.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['acquisition', 'antitrust', 'due diligence', 'tender offer', 'Hart-Scott-Rodino'], sources: ["Black's Law Dictionary"] },
	{ term: 'Board of Directors', definition: 'The governing body of a corporation elected by shareholders to oversee management, set policy, make major business decisions, and appoint officers. Directors owe fiduciary duties of care, loyalty, and good faith to the corporation.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['corporate governance', 'fiduciary duty', 'shareholder', 'officer', 'business judgment rule'], sources: ["Black's Law Dictionary"] },
	{ term: 'Articles of Incorporation', definition: 'The foundational document filed with a state to legally create a corporation. Contains essential information including corporate name, purpose, authorized shares, registered agent, and incorporator information.', category: 'corporate', jurisdiction: 'State', relatedTerms: ['certificate of incorporation', 'charter', 'bylaws', 'formation'], sources: ["Black's Law Dictionary"] },
	{ term: 'Derivative Action', definition: 'A lawsuit brought by a shareholder on behalf of the corporation against a third party, typically corporate officers or directors, when the corporation itself has failed to enforce its own rights. Any recovery goes to the corporation.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['shareholder', 'demand futility', 'business judgment rule', 'corporate governance'], sources: ['Fed. R. Civ. P. 23.1', "Black's Law Dictionary"] },
	{ term: 'Piercing the Corporate Veil', definition: 'A judicial doctrine allowing courts to disregard the corporate entity and hold shareholders personally liable for corporate debts when the corporation is used as a mere alter ego or instrumentality to perpetrate fraud or injustice.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['limited liability', 'alter ego', 'undercapitalization', 'commingling', 'fraud'], sources: ["Black's Law Dictionary"] },
	{ term: 'Business Judgment Rule', definition: 'A judicial presumption that in making a business decision, directors acted on an informed basis, in good faith, and in the honest belief that the action taken was in the best interests of the company. Protects directors from liability for reasonable business decisions.', category: 'corporate', jurisdiction: 'Federal/State', relatedTerms: ['fiduciary duty', 'duty of care', 'board of directors', 'corporate governance'], sources: ["Black's Law Dictionary", 'Aronson v. Lewis, 473 A.2d 805 (Del. 1984)'] },

	// ── Employment Law ──
	{ term: 'At-Will Employment', definition: 'The default employment relationship in most states where either the employer or employee may terminate the relationship at any time, for any reason not prohibited by law, without advance notice. Exceptions include public policy, implied contract, and good faith.', category: 'employment', jurisdiction: 'State', relatedTerms: ['wrongful termination', 'employment contract', 'public policy exception', 'implied contract'], sources: ["Black's Law Dictionary"] },
	{ term: 'Wrongful Termination', definition: 'The dismissal of an employee in violation of a law, public policy, or employment contract. Includes termination based on discrimination, retaliation for whistleblowing, or breach of an implied or express employment agreement.', category: 'employment', jurisdiction: 'Federal/State', relatedTerms: ['at-will employment', 'retaliation', 'discrimination', 'constructive discharge'], sources: ["Black's Law Dictionary"] },
	{ term: 'Workers Compensation', definition: 'A state-mandated insurance program providing benefits to employees who suffer work-related injuries or illnesses regardless of fault. Benefits include medical treatment, disability payments, and vocational rehabilitation. In exchange, employees generally cannot sue their employer for negligence.', category: 'employment', jurisdiction: 'State', relatedTerms: ['workplace injury', 'disability', 'no-fault', 'employer liability'], sources: ["Black's Law Dictionary"] },
	{ term: 'FMLA', definition: 'The Family and Medical Leave Act entitles eligible employees of covered employers to take up to 12 weeks of unpaid, job-protected leave per year for specified family and medical reasons, including birth of a child, serious health condition, or care of a family member.', category: 'employment', jurisdiction: 'Federal', relatedTerms: ['leave of absence', 'job protection', 'serious health condition', 'eligible employee'], sources: ['29 USC §2601-2654'] },
	{ term: 'Sexual Harassment', definition: 'Unwelcome sexual advances, requests for sexual favors, or other verbal or physical conduct of a sexual nature that affects employment. Includes quid pro quo (conditioning benefits on sexual favors) and hostile work environment (pervasive offensive conduct).', category: 'employment', jurisdiction: 'Federal/State', relatedTerms: ['Title VII', 'hostile work environment', 'quid pro quo', 'EEOC', 'retaliation'], sources: ['42 USC §2000e', 'Meritor Savings Bank v. Vinson, 477 U.S. 57 (1986)'] },
	{ term: 'Non-Compete Agreement', definition: 'A contract restricting an employee from working for competitors or starting a competing business for a specified period after leaving employment. Enforceability varies by state; must be reasonable in scope, duration, and geographic area.', category: 'employment', jurisdiction: 'State', relatedTerms: ['restrictive covenant', 'non-solicitation', 'trade secret', 'garden leave'], sources: ["Black's Law Dictionary"] },
	{ term: 'Whistleblower Protection', definition: 'Laws protecting employees from retaliation for reporting illegal activity, safety violations, fraud, or other wrongdoing by their employer. Federal protections exist under numerous statutes including Sarbanes-Oxley, Dodd-Frank, and the False Claims Act.', category: 'employment', jurisdiction: 'Federal/State', relatedTerms: ['retaliation', 'qui tam', 'False Claims Act', 'Sarbanes-Oxley', 'protected activity'], sources: ['18 USC §1514A', '31 USC §3730'] },
	{ term: 'OSHA', definition: 'The Occupational Safety and Health Act and its administering agency, which sets and enforces workplace safety and health standards. Employers must provide a workplace free from recognized hazards and comply with OSHA standards. Employees have the right to report violations.', category: 'employment', jurisdiction: 'Federal', relatedTerms: ['workplace safety', 'hazard', 'inspection', 'citation', 'general duty clause'], sources: ['29 USC §651-678'] },
	{ term: 'Title VII', definition: 'Title VII of the Civil Rights Act of 1964 prohibits employment discrimination based on race, color, religion, sex, or national origin. Applies to employers with 15 or more employees. Enforced by the Equal Employment Opportunity Commission (EEOC).', category: 'employment', jurisdiction: 'Federal', relatedTerms: ['EEOC', 'discrimination', 'disparate treatment', 'disparate impact', 'protected class'], sources: ['42 USC §2000e'] },
	{ term: 'Age Discrimination', definition: 'The Age Discrimination in Employment Act (ADEA) prohibits employment discrimination against individuals 40 years of age or older. Covers hiring, firing, promotion, compensation, and other terms and conditions of employment. Applies to employers with 20 or more employees.', category: 'employment', jurisdiction: 'Federal', relatedTerms: ['ADEA', 'protected class', 'disparate treatment', 'reduction in force', 'EEOC'], sources: ['29 USC §621-634'] },
	{ term: 'Wage and Hour Law', definition: 'Federal and state laws governing minimum wage, overtime pay, recordkeeping, and child labor standards. The Fair Labor Standards Act (FLSA) requires non-exempt employees to receive overtime pay at 1.5 times their regular rate for hours worked over 40 in a workweek.', category: 'employment', jurisdiction: 'Federal/State', relatedTerms: ['FLSA', 'minimum wage', 'overtime', 'exempt', 'non-exempt', 'independent contractor'], sources: ['29 USC §201-219'] },

	// ── Bankruptcy ──
	{ term: 'Chapter 7 Bankruptcy', definition: 'A liquidation bankruptcy in which a trustee sells the debtor\'s non-exempt assets to pay creditors. Remaining eligible debts are discharged. Available to individuals and businesses. Individuals must pass the means test to qualify.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['liquidation', 'discharge', 'means test', 'trustee', 'exempt property'], sources: ['11 USC §701-784'] },
	{ term: 'Chapter 11 Bankruptcy', definition: 'A reorganization bankruptcy primarily used by businesses to restructure debts while continuing operations. The debtor proposes a plan of reorganization to keep its business alive and pay creditors over time. Also available to individuals with substantial debts.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['reorganization', 'plan of reorganization', 'creditor committee', 'debtor in possession'], sources: ['11 USC §1101-1174'] },
	{ term: 'Chapter 13 Bankruptcy', definition: 'A repayment plan bankruptcy for individuals with regular income who wish to keep their property while repaying all or a portion of their debts over a three-to-five-year period. Allows debtors to cure mortgage defaults and keep their homes.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['repayment plan', 'disposable income', 'confirmation', 'mortgage cure'], sources: ['11 USC §1301-1330'] },
	{ term: 'Discharge', definition: 'A court order releasing a debtor from personal liability for certain types of debts. After discharge, creditors can no longer take collection action. Some debts such as student loans, child support, and certain taxes are typically non-dischargeable.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['non-dischargeable debts', 'fresh start', 'reaffirmation', 'Chapter 7', 'Chapter 13'], sources: ['11 USC §524, 727'] },
	{ term: 'Automatic Stay', definition: 'An injunction that takes effect immediately upon filing a bankruptcy petition, halting all collection actions, lawsuits, foreclosures, garnishments, and other creditor actions against the debtor or the debtor\'s property.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['petition', 'relief from stay', 'creditor', 'collection', 'foreclosure'], sources: ['11 USC §362'] },
	{ term: 'Creditor', definition: 'A person or entity to whom the debtor owes money. In bankruptcy, creditors are classified as secured (holding collateral), unsecured priority (taxes, support), or general unsecured, determining the order and likelihood of payment.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['debtor', 'secured creditor', 'unsecured creditor', 'proof of claim', 'priority'], sources: ["Black's Law Dictionary", '11 USC §101'] },
	{ term: 'Debtor', definition: 'A person or entity that owes money to creditors. In bankruptcy, the debtor files a petition seeking relief from debts and is subject to court oversight, reporting requirements, and either liquidation or repayment obligations.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['creditor', 'petition', 'debtor in possession', 'discharge', 'schedules'], sources: ["Black's Law Dictionary", '11 USC §101'] },
	{ term: 'Means Test', definition: 'A formula used to determine whether an individual debtor qualifies for Chapter 7 bankruptcy based on income, expenses, and family size. If the debtor\'s income exceeds the state median, detailed calculations determine whether sufficient disposable income exists to fund a Chapter 13 plan.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['Chapter 7', 'Chapter 13', 'disposable income', 'median income', 'abuse'], sources: ['11 USC §707(b)'] },
	{ term: 'Bankruptcy Trustee', definition: 'A person appointed to administer a bankruptcy estate. In Chapter 7, the trustee liquidates non-exempt assets and distributes proceeds to creditors. In Chapter 13, the trustee oversees the repayment plan and distributes payments.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['estate', 'liquidation', 'distribution', 'fiduciary', 'avoidance powers'], sources: ['11 USC §321-333', "Black's Law Dictionary"] },
	{ term: 'Preferential Transfer', definition: 'A payment or transfer of property made by a debtor to a creditor within 90 days before filing bankruptcy (or one year for insiders) that gives the creditor more than it would receive in a Chapter 7 liquidation. The trustee may avoid and recover such transfers.', category: 'bankruptcy', jurisdiction: 'Federal', relatedTerms: ['avoidance', 'insider', 'ordinary course of business', 'trustee', 'clawback'], sources: ['11 USC §547'] },

	// ── Intellectual Property ──
	{ term: 'Patent', definition: 'A government-granted exclusive right to make, use, sell, or import an invention for a limited period (20 years from filing for utility patents). Requires novelty, non-obviousness, and utility. Protects functional inventions, processes, machines, and compositions of matter.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['utility patent', 'design patent', 'prior art', 'claims', 'infringement', 'USPTO'], sources: ['35 USC §101-103'] },
	{ term: 'Copyright', definition: 'Legal protection for original works of authorship fixed in a tangible medium of expression, including literary, musical, dramatic, and artistic works. Grants exclusive rights to reproduce, distribute, perform, display, and create derivative works. Lasts for the author\'s life plus 70 years.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['fair use', 'derivative work', 'infringement', 'registration', 'DMCA'], sources: ['17 USC §101-1401'] },
	{ term: 'Trademark', definition: 'A word, phrase, symbol, design, or combination that identifies and distinguishes the source of goods or services. Registration provides nationwide constructive notice and the right to use the federal registration symbol. Must be used in commerce to maintain protection.', category: 'intellectual_property', jurisdiction: 'Federal/State', relatedTerms: ['service mark', 'trade dress', 'Lanham Act', 'likelihood of confusion', 'dilution'], sources: ['15 USC §1051-1141n (Lanham Act)'] },
	{ term: 'Trade Dress', definition: 'The overall commercial image or visual appearance of a product or its packaging that serves as a source identifier. Protectable under trademark law if it is distinctive or has acquired secondary meaning and is non-functional.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['trademark', 'secondary meaning', 'functionality doctrine', 'Lanham Act'], sources: ['15 USC §1125(a)', 'Two Pesos v. Taco Cabana, 505 U.S. 763 (1992)'] },
	{ term: 'Fair Use', definition: 'A defense to copyright infringement allowing limited use of copyrighted material without permission for purposes such as criticism, comment, news reporting, teaching, scholarship, or research. Determined by four statutory factors including purpose, nature, amount, and market effect.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['copyright', 'transformative use', 'parody', 'first sale doctrine'], sources: ['17 USC §107', 'Campbell v. Acuff-Rose Music, 510 U.S. 569 (1994)'] },
	{ term: 'Infringement', definition: 'The unauthorized use, reproduction, or exploitation of intellectual property rights including patents, copyrights, trademarks, or trade secrets. Remedies include injunctive relief, actual damages, statutory damages, profits, and attorney fees.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['damages', 'injunction', 'willful infringement', 'contributory infringement'], sources: ["Black's Law Dictionary"] },
	{ term: 'Prior Art', definition: 'Any evidence that an invention was already known before the filing date of a patent application. Includes previous patents, publications, public demonstrations, and commercial products. Used to evaluate novelty and non-obviousness of patent claims.', category: 'intellectual_property', jurisdiction: 'Federal', relatedTerms: ['novelty', 'non-obviousness', 'patent search', 'anticipation'], sources: ['35 USC §102'] },
	{ term: 'Licensing', definition: 'A contractual agreement in which the owner of intellectual property grants permission to another party to use, produce, or sell the protected work under specified conditions. Types include exclusive, non-exclusive, and compulsory licenses.', category: 'intellectual_property', jurisdiction: 'Federal/State', relatedTerms: ['royalty', 'sublicense', 'exclusive license', 'assignment', 'FRAND'], sources: ["Black's Law Dictionary"] },

	// ── Immigration Law ──
	{ term: 'Visa', definition: 'An official authorization permitting a foreign national to enter and remain in a country for a specified purpose and duration. U.S. visa categories include immigrant (permanent), nonimmigrant (temporary), and special visas for specific purposes.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['nonimmigrant', 'immigrant visa', 'H-1B', 'F-1', 'consular processing'], sources: ['8 USC §1101(a)(26)', 'Immigration and Nationality Act'] },
	{ term: 'Green Card', definition: 'An identification card evidencing lawful permanent resident status in the United States. Holders may live and work permanently in the U.S. and may eventually apply for U.S. citizenship through naturalization. Officially known as a Permanent Resident Card.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['permanent resident', 'adjustment of status', 'consular processing', 'naturalization'], sources: ['8 USC §1101(a)(20)', 'INA §101(a)(20)'] },
	{ term: 'Deportation', definition: 'The formal removal of a foreign national from the United States for violating immigration laws. Now officially called "removal." Grounds include criminal convictions, immigration violations, fraud, and security threats. Subject to due process protections.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['removal', 'inadmissibility', 'cancellation of removal', 'voluntary departure', 'expedited removal'], sources: ['8 USC §1227-1229a'] },
	{ term: 'Asylum', definition: 'Protection granted to foreign nationals who have suffered persecution or have a well-founded fear of persecution in their home country based on race, religion, nationality, membership in a particular social group, or political opinion.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['refugee', 'withholding of removal', 'Convention Against Torture', 'credible fear', 'persecution'], sources: ['8 USC §1158', 'INA §208'] },
	{ term: 'Refugee', definition: 'A person outside their country of nationality who is unable or unwilling to return due to persecution or a well-founded fear of persecution. Distinguished from asylees by applying for protection from outside the U.S. through the refugee admissions program.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['asylum', 'resettlement', 'UNHCR', 'persecution', 'protected ground'], sources: ['8 USC §1101(a)(42)', 'INA §101(a)(42)'] },
	{ term: 'Naturalization', definition: 'The legal process by which a foreign national becomes a U.S. citizen. Requirements include lawful permanent residence for a specified period, continuous physical presence, good moral character, English language proficiency, and knowledge of U.S. civics.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['citizenship', 'green card', 'oath of allegiance', 'N-400', 'civics test'], sources: ['8 USC §1421-1459', 'INA §310-347'] },
	{ term: 'DACA', definition: 'Deferred Action for Childhood Arrivals, a federal policy providing temporary protection from deportation and work authorization to individuals who were brought to the U.S. as children and meet certain eligibility requirements. Does not provide a path to citizenship.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['deferred action', 'DREAMers', 'work permit', 'prosecutorial discretion'], sources: ['DHS Memorandum, June 15, 2012'] },
	{ term: 'Adjustment of Status', definition: 'The process of changing from a nonimmigrant or other status to lawful permanent resident (green card holder) status while physically present in the United States, without having to return to one\'s home country for consular processing.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['green card', 'consular processing', 'I-485', 'priority date', 'visa availability'], sources: ['8 USC §1255', 'INA §245'] },
	{ term: 'Immigration Court', definition: 'An administrative court within the Department of Justice where immigration judges hear cases involving foreign nationals charged with immigration violations. Decisions may be appealed to the Board of Immigration Appeals (BIA) and then to federal circuit courts.', category: 'immigration', jurisdiction: 'Federal', relatedTerms: ['EOIR', 'immigration judge', 'BIA', 'removal proceedings', 'appeal'], sources: ['8 USC §1229a'] },

	// ── Estate & Probate ──
	{ term: 'Will', definition: 'A legal document expressing a person\'s wishes regarding the distribution of their property and assets after death. Must generally be in writing, signed by the testator, and witnessed by two competent persons. Types include attested, holographic, and nuncupative.', category: 'estate', jurisdiction: 'State', relatedTerms: ['testament', 'testator', 'beneficiary', 'executor', 'codicil', 'probate'], sources: ["Black's Law Dictionary", 'Uniform Probate Code'] },
	{ term: 'Trust', definition: 'A fiduciary arrangement in which a trustee holds legal title to property for the benefit of one or more beneficiaries. Types include revocable, irrevocable, living (inter vivos), testamentary, charitable, and special needs trusts.', category: 'estate', jurisdiction: 'State', relatedTerms: ['trustee', 'beneficiary', 'settlor', 'fiduciary', 'revocable trust'], sources: ["Black's Law Dictionary", 'Uniform Trust Code'] },
	{ term: 'Probate', definition: 'The court-supervised process of authenticating a will, identifying and inventorying a deceased person\'s property, paying debts and taxes, and distributing the remaining property to the rightful heirs or beneficiaries.', category: 'estate', jurisdiction: 'State', relatedTerms: ['executor', 'administrator', 'intestate', 'estate administration', 'letters testamentary'], sources: ["Black's Law Dictionary", 'Uniform Probate Code'] },
	{ term: 'Executor', definition: 'A person named in a will or appointed by the court to administer the estate of a deceased person. Duties include collecting assets, paying debts and taxes, and distributing the remaining estate according to the will. Also called a personal representative.', category: 'estate', jurisdiction: 'State', relatedTerms: ['administrator', 'personal representative', 'fiduciary', 'probate', 'letters testamentary'], sources: ["Black's Law Dictionary"] },
	{ term: 'Intestate Succession', definition: 'The system of distributing a deceased person\'s property when they die without a valid will. State laws determine who inherits, typically prioritizing surviving spouse, children, parents, and siblings in a prescribed order.', category: 'estate', jurisdiction: 'State', relatedTerms: ['intestacy', 'heirs at law', 'per stirpes', 'per capita', 'escheat'], sources: ["Black's Law Dictionary", 'Uniform Probate Code §2-101'] },
	{ term: 'Beneficiary', definition: 'A person or entity designated to receive benefits from a will, trust, insurance policy, retirement account, or other legal arrangement. Beneficiary designations on financial accounts generally override provisions in a will.', category: 'estate', jurisdiction: 'Federal/State', relatedTerms: ['heir', 'legatee', 'devisee', 'trust', 'will'], sources: ["Black's Law Dictionary"] },
	{ term: 'Power of Attorney', definition: 'A legal document authorizing another person (the agent or attorney-in-fact) to act on one\'s behalf in legal, financial, or medical matters. A durable power of attorney remains effective even if the principal becomes incapacitated.', category: 'estate', jurisdiction: 'State', relatedTerms: ['agent', 'attorney-in-fact', 'durable power of attorney', 'healthcare proxy', 'fiduciary'], sources: ["Black's Law Dictionary", 'Uniform Power of Attorney Act'] },
	{ term: 'Living Will', definition: 'An advance directive document expressing a person\'s wishes regarding life-sustaining medical treatment in the event they become incapacitated and unable to communicate. Also known as an advance healthcare directive.', category: 'estate', jurisdiction: 'State', relatedTerms: ['advance directive', 'healthcare proxy', 'DNR', 'end-of-life care', 'incapacity'], sources: ["Black's Law Dictionary"] },
	{ term: 'Estate Tax', definition: 'A tax imposed on the transfer of the estate of a deceased person. The federal estate tax applies to estates exceeding the exemption amount. Several states also impose state-level estate or inheritance taxes.', category: 'estate', jurisdiction: 'Federal/State', relatedTerms: ['inheritance tax', 'gift tax', 'exemption', 'unified credit', 'step-up in basis'], sources: ['26 USC §2001-2210'] },
	{ term: 'Codicil', definition: 'A written amendment or supplement to an existing will that modifies, adds to, or revokes provisions of the will. Must be executed with the same formalities as the original will, including witnesses and signature.', category: 'estate', jurisdiction: 'State', relatedTerms: ['will', 'amendment', 'revocation', 'testator', 'attestation'], sources: ["Black's Law Dictionary"] },

	// ── Environmental Law ──
	{ term: 'Clean Air Act', definition: 'The comprehensive federal law regulating air emissions from stationary and mobile sources. Authorizes the EPA to establish National Ambient Air Quality Standards (NAAQS) and requires states to develop implementation plans to achieve and maintain those standards.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['EPA', 'NAAQS', 'emission standards', 'SIP', 'criteria pollutants'], sources: ['42 USC §7401-7671q'] },
	{ term: 'Clean Water Act', definition: 'The primary federal law governing water pollution. Establishes the structure for regulating discharges of pollutants into navigable waters and quality standards for surface waters. Requires permits (NPDES) for point source discharges.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['EPA', 'NPDES', 'point source', 'navigable waters', 'wetlands'], sources: ['33 USC §1251-1387'] },
	{ term: 'CERCLA', definition: 'The Comprehensive Environmental Response, Compensation, and Liability Act (Superfund) provides federal authority and funding for cleanup of contaminated hazardous waste sites. Imposes strict, joint and several, and retroactive liability on potentially responsible parties.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['Superfund', 'hazardous waste', 'PRP', 'remediation', 'National Priorities List'], sources: ['42 USC §9601-9675'] },
	{ term: 'NEPA', definition: 'The National Environmental Policy Act requires federal agencies to assess the environmental effects of their proposed actions before making decisions. Mandates environmental impact statements (EIS) for major federal actions significantly affecting the environment.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['EIS', 'environmental assessment', 'FONSI', 'categorical exclusion', 'federal action'], sources: ['42 USC §4321-4347'] },
	{ term: 'Endangered Species Act', definition: 'Federal law providing for the conservation of species that are endangered or threatened and the ecosystems on which they depend. Prohibits taking of listed species and requires federal agencies to ensure their actions do not jeopardize listed species or destroy critical habitat.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['threatened species', 'critical habitat', 'take', 'listing', 'biological opinion'], sources: ['16 USC §1531-1544'] },
	{ term: 'Environmental Impact Statement', definition: 'A detailed document required under NEPA for major federal actions that significantly affect the quality of the human environment. Must describe the proposed action, alternatives, environmental consequences, and mitigation measures.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['NEPA', 'environmental assessment', 'scoping', 'public comment', 'record of decision'], sources: ['42 USC §4332(C)'] },
	{ term: 'Hazardous Waste', definition: 'Waste that poses substantial or potential threats to public health or the environment. Regulated under RCRA, which establishes a cradle-to-grave system for tracking hazardous waste from generation through treatment, storage, and disposal.', category: 'environmental', jurisdiction: 'Federal', relatedTerms: ['RCRA', 'manifest', 'treatment', 'disposal', 'generator'], sources: ['42 USC §6901-6992k'] },

	// ── Administrative Law ──
	{ term: 'Rulemaking', definition: 'The process by which federal agencies create, amend, or repeal regulations. Notice-and-comment rulemaking (informal) requires publication of a proposed rule, a public comment period, and publication of a final rule with responses to comments.', category: 'administrative', jurisdiction: 'Federal', relatedTerms: ['APA', 'notice and comment', 'proposed rule', 'final rule', 'Federal Register'], sources: ['5 USC §553'] },
	{ term: 'Administrative Hearing', definition: 'A proceeding before an administrative law judge (ALJ) to resolve disputes involving government agencies and regulated parties. Less formal than court proceedings but subject to procedural requirements including the right to present evidence and cross-examine witnesses.', category: 'administrative', jurisdiction: 'Federal/State', relatedTerms: ['ALJ', 'administrative law judge', 'adjudication', 'APA', 'agency'], sources: ['5 USC §554-557'] },
	{ term: 'Agency', definition: 'A government body created by statute to administer and enforce specific legislation. Agencies have delegated authority to make rules, adjudicate disputes, and enforce regulations within their area of expertise.', category: 'administrative', jurisdiction: 'Federal/State', relatedTerms: ['delegation', 'rulemaking', 'enforcement', 'regulatory', 'independent agency'], sources: ['5 USC §551(1)', "Black's Law Dictionary"] },
	{ term: 'Delegation Doctrine', definition: 'The constitutional principle governing when Congress may delegate legislative power to executive agencies. Congress must provide an intelligible principle to guide the agency\'s exercise of delegated authority.', category: 'administrative', jurisdiction: 'Federal', relatedTerms: ['non-delegation', 'intelligible principle', 'separation of powers', 'agency authority'], sources: ['J.W. Hampton, Jr., & Co. v. United States, 276 U.S. 394 (1928)'] },
	{ term: 'Exhaustion of Remedies', definition: 'The doctrine requiring a party to exhaust all available administrative remedies before seeking judicial review. Ensures agencies have the opportunity to correct their own errors and develop a factual record for court review.', category: 'administrative', jurisdiction: 'Federal/State', relatedTerms: ['administrative remedy', 'judicial review', 'ripeness', 'final agency action'], sources: ["Black's Law Dictionary"] },
	{ term: 'Judicial Review', definition: 'The power of courts to review agency actions for legality and procedural compliance. Under the APA, courts may set aside agency actions that are arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law.', category: 'administrative', jurisdiction: 'Federal', relatedTerms: ['arbitrary and capricious', 'substantial evidence', 'APA', 'deference', 'Chevron'], sources: ['5 USC §706'] },
	{ term: 'Chevron Deference', definition: 'A judicial doctrine requiring courts to defer to an agency\'s reasonable interpretation of an ambiguous statute it administers. The two-step test asks whether Congress has directly spoken to the issue and, if not, whether the agency\'s interpretation is reasonable.', category: 'administrative', jurisdiction: 'Federal', relatedTerms: ['agency interpretation', 'statutory ambiguity', 'deference', 'Skidmore deference'], sources: ['Chevron U.S.A., Inc. v. NRDC, 467 U.S. 837 (1984)'] },

	// ── Contract Law ──
	{ term: 'Offer', definition: 'A manifestation of willingness to enter into a bargain that justifies another person in understanding that their assent to the bargain is invited and will conclude it. Must be definite, communicated to the offeree, and demonstrate intent to be bound.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['acceptance', 'consideration', 'revocation', 'counteroffer', 'invitation to treat'], sources: ['Restatement (Second) of Contracts §24'] },
	{ term: 'Acceptance', definition: 'A manifestation of assent to the terms of an offer made by the offeree in the manner invited or required by the offer. Under the mirror image rule, acceptance must match the offer exactly; under the UCC, additional terms may be included.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['offer', 'mirror image rule', 'mailbox rule', 'counteroffer', 'UCC §2-207'], sources: ['Restatement (Second) of Contracts §50'] },
	{ term: 'Consideration', definition: 'Something of value exchanged between parties to a contract that makes the agreement legally binding. May be a promise, act, or forbearance. Past consideration and moral obligation are generally insufficient. Adequacy of consideration is not examined by courts.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['bargained-for exchange', 'promissory estoppel', 'illusory promise', 'mutual obligation'], sources: ['Restatement (Second) of Contracts §71'] },
	{ term: 'Capacity', definition: 'The legal ability of a party to enter into a binding contract. Minors, mentally incapacitated persons, and intoxicated persons may lack capacity, rendering contracts voidable at their option. Corporations must act through authorized agents.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['minor', 'mental incapacity', 'voidable', 'ratification', 'disaffirmance'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Contracts §12-16'] },
	{ term: 'Unconscionability', definition: 'A defense to contract enforcement where terms are so unfair or one-sided as to shock the conscience. Requires both procedural unconscionability (unfairness in the bargaining process) and substantive unconscionability (unfair terms).', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['adhesion contract', 'duress', 'undue influence', 'fairness', 'equity'], sources: ['UCC §2-302', 'Restatement (Second) of Contracts §208'] },
	{ term: 'Duress', definition: 'Unlawful pressure or coercion exerted upon a person to force them to enter into a contract or perform an act against their will. Makes a contract voidable. Includes physical threats, economic duress, and improper threats.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['coercion', 'voidable', 'undue influence', 'fraud', 'unconscionability'], sources: ['Restatement (Second) of Contracts §174-176'] },
	{ term: 'Undue Influence', definition: 'Improper persuasion of a person in a position of vulnerability by someone in a position of trust or authority. Overcomes the free will of the influenced party. Common in fiduciary relationships, elder care, and testamentary situations.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['duress', 'fiduciary relationship', 'confidential relationship', 'voidable', 'presumption'], sources: ['Restatement (Second) of Contracts §177'] },
	{ term: 'Reformation', definition: 'An equitable remedy that modifies a written contract to reflect the true agreement of the parties when the writing does not accurately express their mutual intent due to mutual mistake, unilateral mistake with fraud, or scrivener\'s error.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['mutual mistake', 'scrivener\'s error', 'equity', 'rescission', 'rectification'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Contracts §155'] },
	{ term: 'Novation', definition: 'The substitution of a new contract, party, or obligation for an existing one, with the consent of all parties. The original contract is extinguished and replaced. Distinguished from assignment, which transfers rights without extinguishing the original obligation.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['substitution', 'assignment', 'delegation', 'accord and satisfaction'], sources: ["Black's Law Dictionary"] },
	{ term: 'Specific Performance', definition: 'An equitable remedy requiring a party to perform its obligations under a contract, rather than paying damages. Typically awarded when monetary damages are inadequate, such as contracts for the sale of unique property like real estate.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['equitable remedy', 'injunction', 'unique goods', 'real property', 'inadequate remedy at law'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Contracts §357-369'] },
	{ term: 'Statute of Frauds', definition: 'A law requiring certain types of contracts to be in writing and signed to be enforceable. Typically applies to contracts for the sale of land, contracts that cannot be performed within one year, suretyship agreements, and contracts for the sale of goods over $500 (UCC).', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['writing requirement', 'part performance', 'promissory estoppel', 'UCC §2-201'], sources: ["Black's Law Dictionary", 'Restatement (Second) of Contracts §110'] },
	{ term: 'Parol Evidence Rule', definition: 'A rule of contract interpretation that prohibits the introduction of extrinsic evidence of prior or contemporaneous agreements to contradict, vary, or add to the terms of an integrated written contract. Exceptions include fraud, mistake, ambiguity, and condition precedent.', category: 'contract', jurisdiction: 'Federal/State', relatedTerms: ['integration', 'merger clause', 'extrinsic evidence', 'ambiguity', 'interpretation'], sources: ['Restatement (Second) of Contracts §213-216'] },

	// ── Tax Law ──
	{ term: 'Tax Audit', definition: 'An examination of a taxpayer\'s financial records, accounts, and tax returns by the IRS or state tax authority to verify that income, deductions, and credits were reported correctly. May be conducted by mail, in office, or in the field.', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['IRS', 'examination', 'deficiency', 'assessment', 'appeal'], sources: ['26 USC §7601-7613'] },
	{ term: 'Capital Gains', definition: 'The profit realized from the sale of a capital asset such as stocks, bonds, or real estate. Long-term capital gains (assets held over one year) are taxed at preferential rates. Short-term gains are taxed as ordinary income.', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['capital loss', 'basis', 'holding period', 'net investment income tax'], sources: ['26 USC §1(h)', '26 USC §1222'] },
	{ term: 'Tax Deduction', definition: 'An expense that a taxpayer can subtract from gross income to reduce the amount of income subject to tax. Deductions may be standard (a fixed amount) or itemized (specific qualifying expenses such as mortgage interest, state taxes, and charitable contributions).', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['itemized deduction', 'standard deduction', 'adjusted gross income', 'tax credit'], sources: ['26 USC §63, 161-199A'] },
	{ term: 'Tax Evasion', definition: 'The illegal, willful attempt to defeat or circumvent tax laws to avoid paying taxes owed. A felony punishable by fines and imprisonment. Distinguished from tax avoidance, which is the legal use of tax laws to minimize liability.', category: 'tax', jurisdiction: 'Federal', relatedTerms: ['tax fraud', 'willfulness', 'tax avoidance', 'IRS', 'criminal prosecution'], sources: ['26 USC §7201'] },
	{ term: 'Tax Avoidance', definition: 'The legal use of tax planning strategies and provisions within the tax code to minimize tax liability. Distinguished from tax evasion, which involves illegal conduct. Includes deductions, credits, deferrals, and choice of business entity.', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['tax planning', 'tax shelter', 'deduction', 'credit', 'tax evasion'], sources: ["Black's Law Dictionary"] },
	{ term: 'Tax Lien', definition: 'A legal claim by the government against a taxpayer\'s property for unpaid taxes. A federal tax lien arises automatically when a tax assessment is made and payment is not received after demand. May be filed publicly, affecting the taxpayer\'s credit and ability to sell property.', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['levy', 'assessment', 'priority', 'subordination', 'release'], sources: ['26 USC §6321-6327'] },
	{ term: 'Tax Exempt Organization', definition: 'An organization that qualifies for exemption from federal income tax under Section 501(c) of the Internal Revenue Code. Includes charitable, religious, educational, and scientific organizations. Must apply for recognition and comply with operational and reporting requirements.', category: 'tax', jurisdiction: 'Federal', relatedTerms: ['501(c)(3)', 'nonprofit', 'charitable', 'unrelated business income', 'Form 990'], sources: ['26 USC §501'] },
	{ term: 'Withholding', definition: 'The amount of an employee\'s pay retained by the employer and remitted directly to the government as prepayment of the employee\'s income tax liability. Employers also withhold Social Security and Medicare taxes (FICA).', category: 'tax', jurisdiction: 'Federal/State', relatedTerms: ['W-4', 'payroll tax', 'FICA', 'estimated tax', 'Form W-2'], sources: ['26 USC §3401-3406'] },
];

